const mysql=require("mysql2/promise"),{getTargetConfig:getTargetConfig}=require("../db.helper");async function main(){const e=getTargetConfig();let i;try{i=await mysql.createConnection(e);const[t]=await i.query("SELECT id FROM sys_tenants WHERE id = 1");0===t.length&&await i.query("INSERT INTO sys_tenants (id, name, domain_prefix, is_active, created_at) VALUES (1, 'Migrasyon Kliniği', 'migrasyon-klinigi', 1, NOW())")}catch(e){process.exit(1)}finally{i&&await i.end()}}main().catch(console.error);